INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('263952e8-6fc5-4a74-845f-374026eaf29d','db618e68-0656-4b9b-b308-81e071faf745','Cosmo','complete','{"age":"Late 20s","era":"","name":"Cosmo","race":"Werebeast","alias":"","gender":"Male","titles":"Prince of Moonwood Vail\nHeir to Moonwood Vail","subrace":"Dire Wolf","summary":"Cosmo is King Kaelo''s eldest child and a disciplined royal heir of Moonwood Vail. Serious, resourceful, and intellectually minded, he carries responsibility with a controlled presence that reflects the immense dire wolf power beneath his calm exterior. Blessed by Terrax, he commands minerals and sand and can consume crystals to assume specialized crystalline forms.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Royal heir","affiliation":"Wolf Clan","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Tall","Muscular","Powerful"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":"","grooming":"Neatly maintained","skinTone":["Deep warm mahogany"],"wardrobe":"African-inspired royal clothing\nWolf ancestral regalia","hairColor":["Black"],"hairStyle":"Neatly kept tight coils","accessories":"","faceDetails":["Chiseled jawline","High cheekbones","Strong defined features"],"hairTexture":["4C","Tightly coiled"],"colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":["Dire Wolf Form","Sudoform","Burmese Tourmaline Form","Amethyst Form","Obsidian Form","Ruby Form","Emerald Form","Raw Diamond Form","Wulfenite Form","Black Rainbow Titanium Quartz Form","Sapphire Form","Rose Quartz Form","Citrine Form","Aura Quartz Form","Mystic Topaz Form","Dioptase Form"],"clothingStyle":"Traditional African-inspired royal attire incorporating ancestral wolf symbolism and designs suited to his position within Moonwood Vail.","appearanceNotes":"Cosmo''s human appearance emphasizes discipline and contained physical power. His dire wolf nature remains visually suggested through his commanding posture and ancestral clothing even before transformation.","outfitMaterials":"","postureMovement":["Controlled","Still","Commanding"],"signatureOutfit":"African-inspired royal clothing decorated with symbols honoring his wolf ancestors.","distinguishingFeatures":["Serious unwavering gaze","Rare grimace-like smile"]}','{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail","Wolf Clan"],"lineage":"Moonwood Vail royal family","storyArc":"","backstory":"Cosmo was born into King Kaelo''s royal family and raised beneath the responsibilities attached to Moonwood Vail''s Wolf Clan. He was blessed by Terrax, gaining control over minerals and sand. His supernatural physiology also allows him to consume crystals and gemstones and temporarily embody their crystalline properties.","childhood":"","lifestyle":"","storyRole":"Cosmo is the eldest royal child of King Kaelo and heir to Moonwood Vail, carrying the responsibilities of leadership while developing his inherited and bestowed powers.","birthplace":"","psychology":["Burdened by responsibility","Emotionally restrained"],"motivations":["Protect his people","Honor his ancestors"],"personality":["Serious","Disciplined","Resourceful","Intellectual","Reserved","Responsible"],"voiceSpeech":["Few words","Controlled"],"likesDislikes":"","majorLifeEvents":"Blessed by Terrax"}','{"weapons":"","strengths":"Physical strength\nDiscipline\nMineral control\nDefensive combat\nCombat adaptability\nCrystal versatility","weaknesses":"","combatStyle":["Shadow Boxing","Feints","Misdirection"],"limitations":["Crystal forms require consumed material"],"powerSource":["Dire Wolf physiology","Terrax''s blessing","Consumed crystals","Consumed gemstones"],"abilityNotes":"Cosmo can draw minerals from the earth and shape them into weapons and defensive crystal structures. He can manipulate sand into quicksand and animate it into duplicates of himself. His crystal assimilation ability lets him consume different crystals or gemstones and transform his body into corresponding crystalline forms.","combatProfile":"Cosmo combines disciplined physical combat with Shadow Boxing, smooth feints, and misdirection. His mineral and sand manipulation expands his battlefield control through weapons, crystalline defenses, quicksand, and animated sand duplicates. Crystal assimilation allows him to alter his body and dire wolf form according to the gemstone he has consumed.","weaponDetails":"","transformations":"Dire Wolf Form\nSudoform\nBurmese Tourmaline Form\nAmethyst Form\nObsidian Form\nRuby Form\nEmerald Form\nRaw Diamond Form\nWulfenite Form\nBlack Rainbow Titanium Quartz Form\nSapphire Form\nRose Quartz Form\nCitrine Form\nAura Quartz Form\nMystic Topaz Form\nDioptase Form","primaryAbilities":"Mineral Manipulation\nSand Manipulation\nCrystal Assimilation\nCrystal Transformation","secondaryAbilities":"Mineral Extraction\nMineral Weapon Creation\nCrystalline Defense\nQuicksand Creation\nSand Duplication","signatureTechniques":"Sand Duplicates\nCrystal Incasing","transformationDetails":"Cosmo possesses a dire wolf form and an upright humanoid sudoform. After consuming a compatible crystal or gemstone, he gains access to a transformation based on that material. His body becomes encased and hardened in the consumed crystal, including his dire wolf fur, which transforms into hardened crystalline fur. Each consumed material produces a visually distinct crystal form."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Gemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":""}','{"tbdFields":"Eye color\nHeight\nWeight\nBirth date\nMother\nPartner","canonLocks":"Deep warm mahogany skin\nBlack 4C hair\nNeatly kept tight coils\nStrong defined features\nChiseled jawline\nHigh cheekbones\nTall muscular build\nSerious unwavering gaze\nAfrican-inspired clothing\nWolf ancestral symbolism\nDire Wolf Form\nUpright Sudoform\nCrystal-hardened fur","galleryUrl":"","mediaNotes":"Existing visual references establish Cosmo''s human appearance, upright sudoform, dire wolf form, and multiple crystal transformations.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/portrait/1790363585841-cosmo-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nSudoform — Done\nBurmese Tourmaline Form — Done\nAmethyst Form — Done\nObsidian Form — Done\nRuby Form — Done\nEmerald Form — Done\nRaw Diamond Form — Done\nWulfenite Form — Done\nBlack Rainbow Titanium Quartz Form — Done\nSapphire Form — Done\nRose Quartz Form — Done\nCitrine Form — Done\nAura Quartz Form — Done\nMystic Topaz Form — Done\nDioptase Form — Done","productionNotes":"Maintain Cosmo''s established human design, African-inspired ancestral clothing, powerful physique, upright sudoform, dire wolf anatomy, and crystal-hardened fur across transformation references. Individual crystal forms should visually reflect the consumed material while preserving Cosmo''s recognizable silhouette and wolf anatomy.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/reference/1790363591989-cosmo-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/alternate/1790363598396-cosmo-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/263952e8-6fc5-4a74-845f-374026eaf29d/portrait/1790363585841-cosmo-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4','a289d101-2da7-4f15-bfba-51c034e5fda3','615fa3ab-4f1d-47f0-b4f3-5e94e4fbf5fe','2026-09-25T19:27:24.907352+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('34b16e35-6625-4143-b97b-a3b628d60617','db618e68-0656-4b9b-b308-81e071faf745','Calliope','complete','{"age":"Late 20s","era":"500–1300 AD-inspired","name":"Calliope","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Lioness/Dire Wolf Hybrid","summary":"Calliope is one of King Kaelo''s seven children. Fierce, intelligent, confident, and competitive, she carries herself with quiet authority and the controlled grace of a huntress. Her werebeast form combines the grace of a lioness with the powerful legs and heavy paws of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Athletic","Powerful","Feminine"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":["Black — #0B0908"],"skinHex":"","eyeColor":["Golden amber"],"grooming":"","skinTone":["Deep brown"],"wardrobe":"Regal attire\nCombat attire","hairColor":["Black"],"hairStyle":"Thick majestic locs framing her face and falling down her back.","accessories":"Gold hair cuffs\nGold earrings\nGold jewelry","faceDetails":["Long face","Angular features","Confident chin"],"hairTexture":["4C"],"colorPalette":"Black — #0B0908\nTawny Gold\nDark Brown\nGold","dominantHand":"","outfitColors":"Black\nGold","alternateForm":["Lioness/Dire Wolf Werebeast"],"clothingStyle":"Regal fantasy clothing with dark fabrics, gold detailing, and practical construction suited to movement and combat.","appearanceNotes":"Calliope''s human design emphasizes strength, femininity, and predatory confidence. Her thick 4C locs visually echo the powerful silhouette associated with her lioness heritage without becoming a literal mane.","outfitMaterials":["Cloth","Leather","Metal"],"postureMovement":["Fluid","Purposeful","Predatory","Commanding"],"signatureOutfit":"Regal dark fantasy attire with gold detailing, fitted for mobility and a commanding silhouette.","distinguishingFeatures":["Thick long locs","Confident smirk"]}','{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Calliope is one of King Kaelo''s seven children of Moonwood Vail. She developed a fierce, competitive temperament and carries herself with natural authority. Her movements and demeanor reflect the instincts of a patient, confident huntress.","childhood":"","lifestyle":"","storyRole":"","birthplace":"Moonwood Vail","psychology":["Strong-willed","Self-assured","Competitive"],"motivations":"","personality":["Confident","Fierce","Intelligent","Competitive","Authoritative","Fiery"],"voiceSpeech":["Confident","Commanding"],"likesDislikes":"","majorLifeEvents":""}','{"weapons":"","strengths":"Physical Strength\nAgility\nSpeed\nPredatory Senses\nPouncing Power","weaknesses":"","combatStyle":["Predatory","Fluid","Close-range","Pounce-focused"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"","combatProfile":"Calliope fights with fluid, purposeful aggression modeled on a large hunting predator. Her werebeast form emphasizes explosive pounces, powerful limbs, heavy paws, claws, fangs, and close-range physical attacks.","weaponDetails":"","transformations":"Lioness/Dire Wolf Werebeast Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Agility\nEnhanced Speed\nPredatory Senses","secondaryAbilities":"Natural Claws\nNatural Fangs\nPowerful Pounce","signatureTechniques":"","transformationDetails":"Calliope becomes a quadrupedal werebeast approximately the size of a full-grown lioness. Her form has a rich tawny-gold coat, lioness proportions, powerful dire wolf-like legs, and heavy paws. A thick shaggy ruff covers the neck and shoulders, but she has no male lion mane. Her eyes retain the fierce intelligence and predatory focus of her human form."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Calliope is one of King Kaelo''s seven children. Her established siblings are Cosmo, Gemma, Huxleigh, Peregrine, Venny''Claire, and Venny''Macon."}','{"tbdFields":"Mother\nBirth date\nHeight\nWeight\nDominant hand\nOccupation\nWeapons\nSignature techniques\nWeaknesses\nAbility limitations\nPartner\nStory role\nStory arc","canonLocks":"Female\nLate 20s\nKing Kaelo''s child\n4C hair\nThick long locs\nLioness/Dire Wolf hybrid\nTawny-gold werebeast coat\nDire wolf-like legs and paws\nFeminine werebeast form\nNo male lion mane\nMoonwood Vail","galleryUrl":"","mediaNotes":"Human-form character artwork and werebeast-form artwork are established visual references. The future Reference / Production Sheet should consolidate these designs into the primary visual canon reference.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/portrait/1790363775772-calliope-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Needed\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Needed\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Needed\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Preserve Calliope''s established anime/fantasy design across all future artwork. Her human form must retain the same facial structure, deep-brown skin, golden-amber eyes, black 4C locs, feminine athletic build, and dark-and-gold visual identity. Her werebeast form must remain a feminine lioness/dire wolf hybrid with a tawny-gold coat, powerful dire wolf-like legs and paws, and no male lion mane.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/reference/1790363780954-calliope-reference-production-shee.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/alternate/1790363787036-calliope-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/34b16e35-6625-4143-b97b-a3b628d60617/portrait/1790363775772-calliope-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4',NULL,'54d24391-3ed4-445b-8bfe-8dba238fc8e0','2026-09-25T19:27:23.933496+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('37c82673-519e-4ab9-bcea-ed600577eec0','db618e68-0656-4b9b-b308-81e071faf745','Huxleigh','complete','{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Huxleigh","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Polar Bear / Dire Wolf Hybrid","summary":"Huxleigh is one of King Kaelo''s seven children and a powerful werebeast of Moonwood Vail. Large, broad-shouldered, and physically imposing, he carries himself with intimidating confidence and controlled strength. His gruff exterior and frequent scowl conceal a mischievous sense of humor. His werebeast form combines the immense scale of a polar bear with the lean musculature and long snout of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"Moonwood Vail Royal Family","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Large","Broad-shouldered","Dense","Powerful","Muscular"],"nails":"","eyeHex":["Amber — #D88924"],"height":"","makeup":"","weight":"","hairHex":["Black — #11100F"],"skinHex":["Dark Brown — #4A2B20"],"eyeColor":["Amber"],"grooming":"","skinTone":["Rich dark brown"],"wardrobe":"","hairColor":["Black"],"hairStyle":"Short dense curls with faded sides","accessories":"","faceDetails":["Rugged handsome features","Strong jawline","Straight nose","Deep-set eyes"],"hairTexture":["4C","Thick","Tightly curled"],"colorPalette":"Dark Brown — #4A2B20\nBlack — #11100F\nAmber — #D88924\nPolar White — #EEEDE8\nSilver — #BFC2C5\nWolf Gray — #777A7D","dominantHand":"","outfitColors":"","alternateForm":["Monstrous polar bear scale","Dire wolf physique","Long dire wolf snout","White fur","Silver fur","Gray undertones","Thick matted coat"],"clothingStyle":"","appearanceNotes":"Huxleigh''s human form should emphasize dense physical strength rather than exaggerated bulk. His werebeast form is enormous and quadrupedal, combining polar bear mass with the leaner muscular structure and elongated muzzle of a dire wolf. The hybrid silhouette must clearly communicate both bloodlines.","outfitMaterials":"","postureMovement":["Heavy","Direct","Controlled","Graceful","Self-assured"],"signatureOutfit":"","distinguishingFeatures":["Intimidating scowl","Powerful physique"]}','{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Huxleigh is one of King Kaelo''s seven children and belongs to the royal family of Moonwood Vail. Further personal history has not yet been established.","childhood":"","lifestyle":"","storyRole":"Huxleigh is a member of King Kaelo''s royal family and one of his seven children. His larger individual role remains unestablished.","birthplace":"Moonwood Vail","psychology":["Controlled aggression","Strong self-control","Hidden playful streak"],"motivations":"","personality":["Self-assured","Confident","Gruff","Intimidating","Controlled","Mischievous"],"voiceSpeech":["Deep","Gruff","Direct"],"likesDislikes":"","majorLifeEvents":""}','{"weapons":"","strengths":"Immense physical power\nDense musculature\nControlled brute force\nPhysical intimidation\nStrong self-control","weaknesses":"","combatStyle":["Brute force","Direct attacks","Heavy strikes","Controlled aggression"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"No elemental magic, cryokinesis, magical weapons, or other supernatural abilities beyond his established werebeast traits have been confirmed.","combatProfile":"Huxleigh fights through overwhelming physical power and direct aggression while maintaining deliberate control. His tremendous weight and strength do not eliminate his grace or precision. His werebeast form greatly emphasizes close-range physical dominance.","weaponDetails":"","transformations":"Polar Bear / Dire Wolf Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses","signatureTechniques":"","transformationDetails":"Huxleigh becomes a monstrous quadrupedal werebeast the size of an enormous polar bear. His form retains a lean, muscular dire wolf structure and long predatory snout beneath thick white, silver, and gray fur. His amber eyes remain prominent. His growl becomes a deep rumble, while his demeanor shifts toward controlled rage and immense brute force restrained by conscious will."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Huxleigh is one of King Kaelo''s seven children. Individual relationship dynamics with his siblings have not yet been established."}','{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nHeritage\nNationality\nOccupation\nHeight\nWeight\nDominant hand\nSignature outfit\nAccessories\nChildhood\nMajor life events\nGoals\nFears\nBeliefs\nStory arc\nWeapons\nSignature techniques\nWeaknesses\nLimitations\nPartner\nAllies\nRivals\nEnemies\nMentors","canonLocks":"Male\nMid 20s\nKing Kaelo''s son\nOne of seven children\nMoonwood Vail\nRich dark-brown skin\nAmber eyes\nShort thick 4C hair\nFaded sides\nLarge powerful build\nPolar bear / dire wolf hybrid\nWhite and silver beast fur\nGray beast undertones\nLong dire wolf snout\nControlled rage","galleryUrl":"","mediaNotes":"Existing human and werebeast artwork establishes Huxleigh''s visual identity. Generated image text, weapons, tattoos, abilities, measurements, affiliations, or clothing details not established in written canon should not be treated as canon.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/portrait/1790363860158-huxleigh-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Needed\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Future artwork must preserve Huxleigh''s established anime/fantasy design. Human artwork should retain his dark-brown skin, amber eyes, short thick 4C curls with faded sides, rugged face, broad shoulders, and dense muscular build. Werebeast artwork must preserve the polar bear scale, dire wolf anatomy, white and silver fur with gray tones, elongated muzzle, and amber eyes.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/reference/1790363867954-huxleigh-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/alternate/1790363873642-huxleigh-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/37c82673-519e-4ab9-bcea-ed600577eec0/portrait/1790363860158-huxleigh-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4','ec408c98-c948-442c-9c14-74dd07dde097','54d24391-3ed4-445b-8bfe-8dba238fc8e0','2026-09-25T19:27:22.192744+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('808d3a77-faab-458d-9d54-715ac887bb40','db618e68-0656-4b9b-b308-81e071faf745','Sax','complete','{"age":"19","era":"500–1300 AD-inspired","name":"Sax","race":"Duskari","alias":"The Voodoo Assassin","gender":"Male","titles":"The Voodoo Assassin","subrace":"","summary":"Sax is a young Duskari Voodoo Assassin raised in Moonwoodvail. After Captain Blackheart and the Azure Fleet slaughtered his family, his uncle Silas took him in and trained him in Voodoo. Sax weaponized those spiritual teachings into an aggressive assassination style driven by Invocation, Biomancy, shadow magic, and curses.","heritage":"","homeland":"Moonwoodvail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Assassin","affiliation":"Umbra Crew","apparentAge":"19","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""}','{"build":["Lean","Athletic","Muscular","Toned"],"nails":"","eyeHex":["Vibrant Purple — #7B2CBF"],"height":"5''10\"","makeup":"","weight":"","hairHex":["Black — #111111"],"skinHex":["Dark Brown — #70472F"],"eyeColor":["Vibrant purple"],"grooming":"Neat braids with rugged styling","skinTone":["Dark brown"],"wardrobe":"Fur-trimmed vest\nLoose dark trousers\nDeep-red sash\nArm wraps\nLeg wraps\nWrapped sandals","hairColor":["Black"],"hairStyle":"Cornrow braids with loose front braids and red beads","accessories":"Animal-tooth necklace\nTooth earrings\nRed beads\nUpper-arm bands\nAnimal-skull belt buckle\nTwo Voodoo dolls\nFeather bundle\nSpiritual charms","faceDetails":["Sharp eyebrows","Angular features","Confident grin","Small sharp fangs"],"hairTexture":["Tightly coiled"],"colorPalette":"Dark Brown — #70472F\nBlack — #111111\nDeep Red — #711B1B\nBone Ivory — #DDD2BE\nSpirit Purple — #7B2CBF\nTeal — #285B69","dominantHand":"","outfitColors":"Dark brown\nBlack\nDeep red\nBone ivory\nTeal","alternateForm":"","clothingStyle":"Rugged Moonwoodvail assassin attire designed for unrestricted movement. Bone, teeth, beads, feathers, leather, and spiritual charms reinforce his Rootworker influence while preserving a fast close-combat silhouette.","appearanceNotes":"Sax''s established design uses a lean muscular silhouette with minimal armor for speed. His skull belt ornament, Voodoo dolls, bone jewelry, feather accents, braided hairstyle, and twin ornate daggers are major visual identifiers.","outfitMaterials":["Leather","Fur","Cloth","Bone","Feathers","Cord","Metal"],"postureMovement":["Predatory","Agile","Fast","Combat-ready"],"signatureOutfit":"Sax wears an open sleeveless brown vest with fur trim, bone fasteners, loose dark trousers, arm wraps, rugged leg wraps, and a deep-red waist sash. An animal skull decorates his belt, two Voodoo dolls hang at his waist, and a feather bundle adds red, white, and teal accents.","distinguishingFeatures":["Small fangs","Red hair beads","Tooth earrings","Bone ornaments"]}','{"fears":["Losing another family","Failing his loved ones","Mental manipulation"],"goals":["Kill Captain Blackheart","Protect the Umbra Crew","Master Voodoo Roguery"],"beliefs":["Respect the ancestors","Protect those you love","Loyalty demands action"],"culture":["Moonwoodvail","Rootworking","Voodoo","Ancestor communion","Crossroads spirituality"],"lineage":"Duskari","storyArc":"Sax begins as a young fighter consumed by vengeance against Captain Blackheart. Training under Silas gradually forces him to refine his volatile emotions into disciplined spiritual combat. His bond with Kaelen and the Umbra Crew gives him people to protect beyond the family he lost.","backstory":"Captain Blackheart and the Azure Fleet slaughtered Sax''s family during the Crimson Tide Tragedy. Sax survived because his mother hid him during the raid. His uncle Silas took custody of him and attempted to teach him the healing and protective traditions of Voodoo, but Sax''s desire for vengeance led him to weaponize those teachings into an assassination-focused fighting style.","childhood":"Sax grew up in Moonwoodvail alongside Asha, Keno, Mali, and Rico. Their tight-knit peer group gave him a strong sense of community despite his naturally hot temper. His childhood ended violently when Captain Blackheart and the Azure Fleet attacked his coastal village.","lifestyle":["Aggressive combat training","Spiritual practice","Target hunting","Traveling with the Umbra Crew"],"storyRole":"Sax is an emotional lightning rod within the early Umbra Crew and one of Kaelen''s first true friends. His clear desire for vengeance contrasts with Kaelen''s uncertainty about his missing memories. Sax''s hatred of corruption pushes the group forward while his fierce loyalty helps keep Kaelen grounded.","birthplace":"Moonwoodvail","psychology":["Trauma-driven anger","Survivor grief","Vengeance fixation","Protective attachment","Emotionally reactive"],"motivations":["Avenge his family","Protect Kaelen","Destroy the Azure Fleet","Master his spiritual power"],"personality":["Hot-tempered","Fiercely loyal","Brash","Impulsive","Protective","Vengeful","Determined","Gritty","Competitive"],"voiceSpeech":["Blunt","Sharp","Emotionally charged","Quick-tempered"],"likesDislikes":["His crew","Challenges","Spicy food","Silas''s old stories","Dislikes vampires","Dislikes betrayal","Dislikes corrupt authority","Hates being tricked"],"majorLifeEvents":"Childhood in Moonwoodvail\nCrimson Tide Tragedy\nFamily slaughtered\nSurvived the Azure Fleet raid\nTaken in by Silas\nTrained in Voodoo\nBegan hunting Captain Blackheart\nMet Kaelen at Sunstone Coast\nJoined forces with Kaelen\nReturned to Moonwoodvail with Kaelen\nTrained under Silas"}','{"weapons":"Twin Shadow Daggers\nVoodoo Dolls","strengths":"Extreme speed bursts\nFast reflexes\nClose-range combat\nSpiritual curses\nMental attacks\nHigh agility\nAssassination tactics","weaknesses":"Hot temper\nMental charms\nSpiritual manipulation\nImpulsiveness\nEmotional instability","combatStyle":["Voodoo Roguery","Dual-blade combat","Close-range assassination","High-speed movement","Mid-combat curse weaving","Shadow-enhanced strikes"],"limitations":["Sympathetic magic needs a connection","Blood curse requires prior contact","Spiritual Surge consumes life-force","Emotion disrupts concentration"],"powerSource":["Invocation","Biomancy","Spiritual energy","Ancestor spirits","Voodoo"],"abilityNotes":"Shadow-Cloaked Blades can temporarily disrupt Chronoessence conduits where Sax strikes. Grave Flashback overwhelms an enemy''s spiritual senses and forces traumatic memories or fears to the surface. Phantom Requiem: Thousand Curses summons spectral shadow-hands to restrain an enemy while Sax delivers a rapid sequence of shadow-cloaked strikes whose energy trails detonate in succession.","combatProfile":"Sax fights at close range rather than relying on stationary rituals. He channels Invocation through his spiritual techniques and Biomancy through his body, accelerating his muscles and nervous system with Spiritual Surge. His style combines rapid dual-blade attacks, shadow cloaking, sympathetic curses, and aggressive psychic assaults.","weaponDetails":"Sax dual-wields ornate curved daggers for rapid close-range attacks. He cloaks the blades in dark spiritual shadow capable of cutting physical targets and disrupting Chronoessence conduits. His blank Voodoo dolls become weapons for sympathetic curses after he obtains a physical connection to a target.","transformations":"","primaryAbilities":"Shadow-Cloaked Blades\nSpiritual Surge\nSympathetic Magic\nPsychomancy\nSpirit Channeling\nAncestor Communion","secondaryAbilities":"Sciomancy\nPhysical enhancement\nSpiritual tracking\nCurse weaving\nMental disruption","signatureTechniques":"Shadow-Cloaked Blades\nSpiritual Surge\nSympathetic Curse\nGrave Flashback\nPhantom Requiem: Thousand Curses","transformationDetails":""}','{"allies":"Kaelen Thorne\nAsha\nKeno\nMali\nUmbra Crew","rivals":"Zafir\nRico","enemies":"Captain Blackheart\nAzure Fleet","mentors":"Silas\nMama Eve","parents":"","partner":"","children":"","siblings":"","worldConnections":"Moonwoodvail\nSunstone Coast\nAethelgard","relationshipNotes":"Silas is Sax''s uncle and primary Voodoo mentor, taking custody of him after the destruction of his family. Kaelen becomes Sax''s first close companion after they fight Blackheart''s thugs together near the Sunstone Coast, and Sax becomes fiercely protective of him. Sax has an explosive rivalry with Zafir, whose teasing and mini-form antics regularly provoke him. Asha, Keno, Mali, and Rico belong to Sax''s childhood Moonwoodvail peer group."}','{"tbdFields":"Birth date\nName meaning\nElemental heritage\nSubrace\nHeritage\nNationality\nCurrent residence\nWeight\nDominant hand\nParents'' names\nSiblings\nPartner","canonLocks":"Duskari\nMale\nMoonwoodvail origin\nSilas''s nephew\nCrimson Tide survivor\nCaptain Blackheart killed his family\nAzure Fleet destroyed his family\nVoodoo Roguery\nInvocation\nBiomancy\nTwin shadow daggers\nPurple eyes\nCornrow braids\nRed hair beads\nKaelen''s close friend\nZafir rivalry","galleryUrl":"","mediaNotes":"Future artwork must follow the established production sheet and full-body reference. Do not redesign Sax''s face, skin tone, eyes, hairstyle, physique, signature outfit, weapons, or primary palette.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/portrait/1790363965860-sax-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Needed\nFace Reference — Done\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"The established Reference / Production Sheet is Sax''s primary visual canon. Preserve his dark skin, purple eyes, cornrow braids with red beads, lean muscular build, fur-trimmed vest, bone ornaments, deep-red sash, skull belt piece, Voodoo dolls, feather accents, and ornate twin daggers. Spiritual blade energy should remain dark purple and black.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/reference/1790363972828-sax-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/alternate/1790363979976-sax-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/portrait/1790363965860-sax-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','baaf3d0d-afe5-4ad3-92e2-14dbe7cbd5e0','bd19189f-d8ba-4190-af7a-4c9df16e50c9','0b04c5a0-22fd-4442-a86d-eea0aeb15514','2026-09-25T19:27:21.506892+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('27d2993d-dc47-4027-9d2d-d0daed6b43c2','db618e68-0656-4b9b-b308-81e071faf745','Peregrine','complete','{"age":"","era":"500–1300 AD-inspired","name":"Peregrine","race":"Werebeast","alias":"","gender":"Male","titles":"Prince of Moonwood Vail","subrace":"Fox-Dire Wolf Werebeast","summary":"Peregrine is a lithe and cunning prince of Moonwood Vail whose strengths lie in agility, deception, and illusion. Smaller than his older siblings, he developed a competitive streak and a constant need to prove that he is every bit as dangerous. He carries himself with sly confidence, natural elegance, and a sharp awareness of his surroundings.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Prince","affiliation":"Moonwood Vail Royal Family","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Lithe","Slender","Lean","Agile"],"nails":"","eyeHex":["Amber Brown — #A8662B"],"height":"Medium height","makeup":"","weight":"","hairHex":["Black — #15120F"],"skinHex":["Warm Caramel — #A96845"],"eyeColor":["Amber-brown"],"grooming":"Neat and stylish","skinTone":["Warm caramel"],"wardrobe":"Short linen tunic\nFitted trousers\nLeather ankle ties\nWide leather belt\nShort shoulder cloak","hairColor":["Black"],"hairStyle":"Loose stylish afro","accessories":"Metal cloak brooch\nLeather belt\nDagger sheaths","faceDetails":["Sly fox-like face","Sharp features","Expressive brows"],"hairTexture":["4C"],"colorPalette":"Black — #151515\nDark Brown — #3A281E\nWarm Caramel — #A96845\nWarm Red — #9A3F27\nDark Grey — #3B3A3A","dominantHand":"","outfitColors":"Black\nCharcoal\nDark brown","alternateForm":["Fox-Dire Wolf Werebeast Form"],"clothingStyle":"Peregrine favors dark, lightweight garments designed for maximum movement and stealth. His clothing remains practical while retaining the understated refinement expected of Moonwood Vail nobility.","appearanceNotes":"Peregrine is the most lithe and slender of his brothers and the shortest of his older siblings. His silhouette should emphasize speed and agility rather than physical bulk. His sharp face, loose 4C afro, sly smirk, and confident bearing should remain consistent across artwork.","outfitMaterials":["Dark linen","Leather","Metal"],"postureMovement":["Natural elegance","Confident swagger","Quick movements","Graceful movements","Purposeful movements"],"signatureOutfit":"A tightly woven dark linen tunic cut short for unrestricted movement with period-appropriate trousers secured by leather ties at the ankles. A wide leather belt holds his daggers, while a short dark linen cloak is draped over one shoulder and secured with a metal brooch.","distinguishingFeatures":["Sly smirk","Fox-like features"]}','{"fears":["Being dismissed as weak","Being overshadowed"],"goals":["Master illusion","Remain unpredictable","Prove his capability"],"beliefs":["Cunning can defeat strength","Size does not determine danger"],"culture":["Moonwood Vail","Werebeast royalty"],"lineage":"Moonwood Vail Royal Family","storyArc":"Peregrine''s established internal conflict centers on his need to prove that his smaller stature does not make him less dangerous or capable than his siblings. Further story developments remain unestablished.","backstory":"Peregrine grew into a clever and agile member of Moonwood Vail''s royal family. His smaller stature became both an insecurity and a driving force, pushing him toward mastery of illusion and deception. He learned to make unpredictability, speed, and intelligence more dangerous than brute strength.","childhood":"Growing up smaller than his older siblings contributed to Peregrine''s competitive nature and strong need to prove himself. Rather than relying on physical size, he developed cunning, agility, wit, and deception as his defining strengths.","lifestyle":["Practices agility","Practices deception","Maintains mobility-focused clothing"],"storyRole":"Peregrine represents cunning, deception, and agility among King Kaelo''s children. His smaller stature distinguishes him from his physically larger siblings and encourages him to approach danger through intelligence, misdirection, and speed.","birthplace":"Moonwood Vail","psychology":["Short guy complex","Needs to prove himself","Dislikes underestimation","Highly competitive"],"motivations":["Prove his worth","Outsmart stronger opponents","Match his siblings"],"personality":["Cunning","Competitive","Confident","Sly","Clever","Observant","Free-spirited","Prideful","Witty"],"voiceSpeech":["Sharp wit","Confident delivery","Playful taunting"],"likesDislikes":["Likes competition","Likes clever victories","Likes proving himself","Dislikes being underestimated","Dislikes size comparisons"],"majorLifeEvents":""}','{"weapons":"Daggers","strengths":"Agility\nSpeed\nCunning\nDeception\nObservation\nIllusion\nQuick thinking","weaknesses":"Smaller stature\nCompetitive pride\nNeed to prove himself","combatStyle":["Agile","Deceptive","Evasive","Dagger-based","Misdirection-focused","Precision-focused"],"limitations":["Less physically imposing","Illusion limits unestablished"],"powerSource":["Werebeast nature","Illusion mastery"],"abilityNotes":"Peregrine is established as a master of deception and illusion. Exact illusion techniques, ranges, costs, and restrictions have not yet been established.","combatProfile":"Peregrine favors speed, misdirection, illusions, and precision over direct contests of strength. His quick movements and deceptive tactics keep opponents uncertain of his true position and intentions. His smaller werebeast form further emphasizes agility rather than overwhelming physical power.","weaponDetails":"Peregrine carries daggers at his waist for fast, precise attacks that complement his agile fighting style. Their exact design and number have not been established.","transformations":"Fox-Dire Wolf Werebeast Form","primaryAbilities":"Illusion\nDeception","secondaryAbilities":"Enhanced agility\nEnhanced senses\nRapid movement\nStealth\nSharp observation","signatureTechniques":"","transformationDetails":"Peregrine''s werebeast form is approximately the size of a large fox, making him smaller than his siblings'' werebeast forms. It combines fox-like proportions with powerful dire wolf limbs and a dense coat. His fur blends vibrant reds and warm caramel, shifting to dark grey around his dire wolf-like paws. His sharp, intelligent eyes and agile movements preserve his cunning personality in this form."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Peregrine is one of King Kaelo''s seven children. His smaller stature compared with his older siblings contributes to his competitive personality and desire to prove himself."}','{"tbdFields":"Age\nBirth date\nPronunciation\nName meaning\nExact height\nExact weight\nDominant hand\nMother\nPartner\nAllies\nRivals\nEnemies\nMentors\nExact dagger design\nExact illusion techniques\nIllusion limitations","canonLocks":"Male\nHe/Him\nKing Kaelo''s son\nOne of seven siblings\nMoonwood Vail\nWerebeast\nWarm caramel skin\nLoose 4C afro\nLithe slender build\nShortest older sibling\nIllusion mastery\nDeception mastery\nDaggers\nFox-Dire Wolf form\nSmaller werebeast form\nRed and caramel fur\nDark grey paws","galleryUrl":"","mediaNotes":"Existing artwork establishes Peregrine''s human appearance, fantasy clothing, daggers, expressions, and Fox-Dire Wolf werebeast design. Future artwork should preserve the established visual continuity.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/portrait/1790364115845-peregrine-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Peregrine''s established anime/fantasy design across future artwork. His human form must remain lithe, slender, warm caramel-skinned, sharp-featured, and characterized by loose 4C hair. His werebeast form must remain smaller than his siblings'' forms and preserve its red, caramel, and dark grey coloration.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/reference/1790364122249-peregrine-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/alternate/1790364130239-peregrine-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/27d2993d-dc47-4027-9d2d-d0daed6b43c2/portrait/1790364115845-peregrine-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4','ec408c98-c948-442c-9c14-74dd07dde097','615fa3ab-4f1d-47f0-b4f3-5e94e4fbf5fe','2026-09-25T19:27:19.126065+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('60e6b4b0-fa5e-46ed-b202-7d8cea244f87','db618e68-0656-4b9b-b308-81e071faf745','Gemma','complete','{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Gemma","race":"Werebeast","alias":"","gender":"Female","titles":"Princess of the Monkey Clan","subrace":"Were-Gorilla","summary":"Gemma is a princess of Moonwood Vail and the spiritual intermediary among King Kaelo''s children. A devoted scholar of Voodoo and the Loa, she combines ancestral spirituality, ritual drumming, and immense were-gorilla strength. She is destined to become the chosen human vessel of Gōurīrā Loa, the trickster spirit of the Monkey King.","heritage":"","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"Princess","affiliation":"Monkey Clan","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"Moonwoodvail","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Tall","Slender","Graceful"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":["Black — #141114"],"skinHex":["Deep Ebony — #321F1B"],"eyeColor":["Dark brown"],"grooming":"Neatly maintained braids","skinTone":["Deep rich ebony"],"wardrobe":"Wrapper skirts\nWide-sleeved blouses\nCeremonial attire","hairColor":["Black"],"hairStyle":"Intricate tightly coiled braids","accessories":"Bone-rimmed spectacles\nCowrie shells\nPolished wooden beads\nWooden talisman necklace\nRiver stone necklace","faceDetails":["Soft features","Dreamy expression","Small upturned nose"],"hairTexture":["4C"],"colorPalette":"Ebony — #321F1B\nLinen — #E7DDC8\nWood Brown — #75543A\nRiver Stone — #68675F","dominantHand":"","outfitColors":"Natural linen\nEarth brown\nStone grey","alternateForm":["Were-Gorilla Form","Full Gorilla Mode"],"clothingStyle":"Period-appropriate African-inspired clothing emphasizing natural fabrics, flowing silhouettes, practical movement, and spiritual adornments.","appearanceNotes":"Gemma''s delicate, scholarly human appearance contrasts strongly with her powerful werebeast forms. Her visual design should maintain an ethereal, meditative quality without diminishing her underlying physical and spiritual strength.","outfitMaterials":["Linen","Cotton","Wood","River stone"],"postureMovement":["Quiet","Gliding","Grounded"],"signatureOutfit":"An undyed linen wrapper-and-blouse ensemble. The rectangular wrapper is tied at the waist as a flowing skirt, while the loose blouse has wide sleeves for comfort and movement.","distinguishingFeatures":["Bone-rimmed spectacles","Cowrie-adorned braids","Wooden hair beads"]}','{"fears":"","goals":["Master spiritual practices","Deepen her Loa connection"],"beliefs":["Respect for ancestors","Respect for the Loa","Spiritual coexistence","Clan unity"],"culture":["Moonwoodvail","Monkey Clan","Voodoo traditions","Ancestral spirituality","African drumming traditions"],"lineage":"Royal Moonwoodvail lineage","storyArc":"Gemma''s growing understanding of Voodoo and the Loa prepares her for her destined union with Gōurīrā Loa. This bond expands her abilities from ancestral assistance into powerful spiritual chaos, illusion, and reality manipulation.","backstory":"Gemma was born into Moonwoodvail''s royal family as a daughter of King Kaelo and the Queen of the Monkey Clan. She developed a deep fascination with Voodoo, the Loa, ancestral spirits, and ritual practices. Her spiritual studies eventually became inseparable from her combat abilities and drumming.","childhood":"","lifestyle":["Studies Voodoo","Studies the Loa","Plays African drums","Practices spiritual rituals"],"storyRole":"Gemma serves as a spiritual bridge between Moonwood Vail''s physical and spiritual worlds. Her scholarship and connection to Gōurīrā Loa give her a distinct role among King Kaelo''s children.","birthplace":"Moonwood Vail","psychology":["Spiritually inquisitive","Deeply contemplative","Comfortable with the unseen"],"motivations":["Understand the Loa","Preserve ancestral knowledge","Protect Moonwood Vail","Serve her clan"],"personality":["Intelligent","Dreamy","Studious","Calm","Grounded","Playful","Mischievous","Spiritually curious"],"voiceSpeech":["Soft-spoken","Thoughtful","Playful when relaxed"],"likesDislikes":["Voodoo","Loa","African drums","Ancestral knowledge","Spiritual study"],"majorLifeEvents":"Studied Voodoo\nStudied the Loa\nBecame a spiritual intermediary\nChosen by Gōurīrā Loa"}','{"weapons":"African Drums","strengths":"Immense physical strength\nSpiritual versatility\nPowerful grappling\nAncestral assistance\nSensory deception\nHigh agility","weaknesses":"","combatStyle":["Spirit Brawler","Close-quarters combat","Grappling","Spiritual misdirection"],"limitations":"","powerSource":["Werebeast physiology","Ancestral spirits","Loa","Gōurīrā Loa"],"abilityNotes":"Gōurīrā Loa is the trickster spirit of the Monkey King and Gemma''s destined Loa. Their union grants wild, liberating chaos energy capable of shifting reality, manipulating perception through sensory illusions, and reinforcing Gemma''s physical attacks with spiritual force.","combatProfile":"Gemma combines the physical strength of her were-gorilla form with unpredictable spiritual intervention. Her deep rhythmic chest beats act as calls toward the spiritual plane. Gōurīrā Loa''s influence allows her to introduce chaos, sensory deception, and spiritual weight into otherwise direct physical combat.","weaponDetails":"Gemma uses African drums as spiritual instruments rather than conventional weapons. Rhythmic patterns can accompany her communion with spirits and ancestral forces.","transformations":"Were-Gorilla Form\nFull Gorilla Mode","primaryAbilities":"Ancestral Assistance\nSpirit Channeling\nEnhanced Strength\nSensory Illusions\nReality Shifting\nSpiritual Reinforcement","secondaryAbilities":"Ritual Drumming\nSpirit Communication\nEnhanced Agility\nEnhanced Durability","signatureTechniques":"Rhythmic Spirit Call\nSpiritual Chest Beat","transformationDetails":"Her were-gorilla form stands around five and a half feet tall with a compact, heavily muscled build, broad shoulders, deep chest, long powerful arms, and a tapered waist. Midnight-black fur carries subtle violet undertones, while longer golden-brown fur forms a mane around her face and neck. Her amber eyes remain expressive, crimson geometric spiritual markings glow beneath the fur along her collarbones and forearms, and a short golden tail-tuft reacts to her mood. Full Gorilla Mode becomes more completely gorilla-like while retaining her black coat, golden-brown mane, amber eyes, spiritual markings, and immense physical power."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Gemma''s mother is the Queen of the Monkey Clan, but her personal name has not been established. Gemma is one of King Kaelo''s seven children."}','{"tbdFields":"Mother''s name\nHuman eye color\nHuman height\nHuman weight\nDominant hand","canonLocks":"Deep rich ebony skin\n4C braided hair\nBone-rimmed spectacles\nCowrie shells\nWooden hair beads\nNatural linen clothing\nWere-gorilla transformation\nMidnight-black werebeast fur\nGolden-brown werebeast mane\nAmber werebeast eyes\nCrimson spiritual markings\nGolden tail-tuft\nAfrican drums\nGōurīrā Loa connection","galleryUrl":"","mediaNotes":"Existing visual references establish Gemma''s anime-inspired human appearance, were-gorilla form, and full gorilla mode.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/portrait/1790364214194-gemma-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nWere-Gorilla Form — Done\nFull Gorilla Mode — Done","productionNotes":"Maintain a high-detail anime fantasy aesthetic. Her human design should emphasize her scholarly, spiritual presence, while her were-gorilla design should balance formidable physical power with feminine, playful expressiveness.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/reference/1790364310030-gemma-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/alternate/1790364230710-gemma-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/60e6b4b0-fa5e-46ed-b202-7d8cea244f87/portrait/1790364214194-gemma-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4','43c09341-d62a-4297-adba-d3e083f3e202','97cc57ef-5f5b-4011-95ed-481f61480c26','2026-09-25T19:27:18.283644+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('18527db0-a1c0-4b40-875d-8d911067a94a','db618e68-0656-4b9b-b308-81e071faf745','King Kaelo','complete','{"age":"","era":"","name":"King Kaelo","race":"Werebeast","alias":"The Spiritual Anchor","gender":"Male","titles":"King","subrace":"Dire Wolf","summary":"King Kaelo is the independent ruler of Moonwood Vail and the father of seven formidable werebeast children. A pure Dire Wolf werebeast, he protects his realm through immense physical strength, spiritual discipline, and Ogou-Style Martial Arts. His rule has successfully kept King Vorlag''s tyranny outside Moonwood Vail''s borders.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"King","affiliation":"Moonwood Vail","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Tall","Powerful","Athletic"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":"","grooming":"Neatly groomed","skinTone":["Deep mahogany"],"wardrobe":"Royal robes\nCombat attire\nFur mantle","hairColor":["Black"],"hairStyle":"Medium-length dreads","accessories":"Gold jewelry","faceDetails":["Sharp facial features","Strong jawline"],"hairTexture":["4c"],"colorPalette":"Black\nGold\nMahogany","dominantHand":"","outfitColors":"Black\nGold","alternateForm":["Pure Dire Wolf"],"clothingStyle":"Regal dark clothing combining royal authority with practical martial attire.","appearanceNotes":"Kaelo has a commanding royal presence with deep mahogany skin, sharp features, and medium-length 4c dreads. His physical design should communicate both disciplined martial strength and the authority of an independent ruler.","outfitMaterials":["Fabric","Leather","Fur","Metal"],"postureMovement":["Commanding","Regal","Grounded"],"signatureOutfit":"Regal black attire with gold detailing and a dark fur mantle.","distinguishingFeatures":""}','{"fears":"","goals":["Maintain Moonwood Vail''s sovereignty"],"beliefs":"","culture":["Moonwood Vail"],"lineage":"","storyArc":"","backstory":"Kaelo became the independent king of Moonwood Vail and maintained the realm''s sovereignty against King Vorlag''s expansion and tyranny. He became the spiritual and martial anchor of his family while raising seven powerful werebeast children.","childhood":"","lifestyle":["Royal leadership","Martial training"],"storyRole":"Kaelo serves as the spiritual anchor of the Moonwood Vail royal family and the ruler who keeps outside tyranny from consuming his homeland.","birthplace":"","psychology":["Strong sense of responsibility","Protective of his family","Protective of his realm"],"motivations":["Protect his children","Protect Moonwood Vail","Preserve independence"],"personality":["Independent","Protective","Disciplined","Commanding","Resolute"],"voiceSpeech":["Authoritative","Measured","Direct"],"likesDislikes":"","majorLifeEvents":"Became King of Moonwood Vail\nDefended Moonwood Vail from King Vorlag"}','{"weapons":"","strengths":"Extreme physical strength\nSpiritual discipline\nClose-range combat\nHigh durability\nBattlefield disruption","weaknesses":"","combatStyle":["Ogou-Style Martial Arts","Close-quarters combat","Aura-enhanced striking"],"limitations":"","powerSource":["Spiritual energy","Werebeast physiology"],"abilityNotes":"Kaelo''s golden aura reinforces his strikes with battering-ram force. His projected shockwave can level structures and scatter infantry formations.","combatProfile":"Kaelo fights through Ogou-Style Martial Arts, infusing his physical strikes with iron-hard golden spiritual energy. His blows carry tremendous concussive force, allowing him to overwhelm opponents through disciplined close-range combat rather than relying on conventional weapons. He can also project his accumulated spiritual force outward across the battlefield.","weaponDetails":"","transformations":"Pure Dire Wolf Form","primaryAbilities":"Golden Aura Manipulation\nSpiritual Energy Projection\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Speed\nEnhanced Senses\nDire Wolf Transformation","signatureTechniques":"Golden Shockwave","transformationDetails":"Kaelo transforms into a pure Dire Wolf werebeast. The transformation greatly enhances his natural physical power, durability, speed, and predatory capabilities."}','{"allies":"","rivals":"","enemies":"King Vorlag","mentors":"","parents":"","partner":"","children":"Cosmo\nCalliope\nHuxleigh\nGemma\nPeregrine\nVenny’Claire\nVenny’Macon","siblings":"","worldConnections":"Moonwood Vail","relationshipNotes":"Kaelo is the father of seven werebeast children and serves as the central spiritual and martial authority of the royal family. His opposition to King Vorlag is rooted in protecting Moonwood Vail from Vorlag''s tyranny."}','{"tbdFields":"","canonLocks":"Deep mahogany skin\nBlack 4c hair\nMedium-length dreads\nPowerful build\nPure Dire Wolf form\nBlack-and-gold palette\nGolden spiritual aura\nOgou-Style Martial Arts","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/18527db0-a1c0-4b40-875d-8d911067a94a/portrait/1790360382571-king-kaelo-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Preserve Kaelo''s deep mahogany skin, black medium-length 4c dreads, powerful build, regal black-and-gold presentation, and pure Dire Wolf transformation. His golden spiritual aura should remain the primary visual language of his combat abilities.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/18527db0-a1c0-4b40-875d-8d911067a94a/reference/1790360398954-king-kaelo-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/18527db0-a1c0-4b40-875d-8d911067a94a/alternate/1790360411311-king-kaelo-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/18527db0-a1c0-4b40-875d-8d911067a94a/portrait/1790360382571-king-kaelo-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4','df5399c6-b9f2-4ad4-bfbe-d9bc5d7f426b',NULL,'2026-09-25T19:25:38.732179+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('e229597e-305b-42fe-b232-1f78f3ac5735','db618e68-0656-4b9b-b308-81e071faf745','Venny''Macon','complete','{"age":"","era":"","name":"Venny''Macon","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Werepanther","summary":"Venny''Macon is one of King Kaelo''s children and the mirror counterpart of Venny''Claire. Quiet and reserved, he possesses immense strength that he has yet to fully understand or embrace. His uncertainty contrasts with the tremendous potential sleeping within him.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Sturdy","Muscular","Broad-shouldered"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Knee-length tunic\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGhost White\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown","alternateForm":["White Werepanther","Sudo Form"],"clothingStyle":"Simple, practical clothing suited to the climate and active life of Moonwood Vail.","appearanceNotes":"Venny''Macon closely mirrors Venny''Claire in facial structure, complexion, eyes, and hair. He is slightly taller and sturdier than his sister, with greater visible muscular development.","outfitMaterials":["Woven linen","Leather"],"postureMovement":["Reserved posture","Powerful movement"],"signatureOutfit":"Simple knee-length woven linen tunic secured with a braided leather cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]}','{"fears":["His own potential"],"goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"His arc follows the gradual awakening of his immense potential and his struggle to gain confidence in his own strength.","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Macon embodies the sleeping giant: immense natural power restrained by uncertainty and reluctance. His development centers on learning to understand and accept the strength already within him.","birthplace":"","psychology":["Unsure of his potential","Reluctant to embrace his power"],"motivations":"","personality":["Quiet","Reserved","Timid","Uncertain","Kind-hearted"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""}','{"weapons":"","strengths":"Immense physical strength\nHigh durability\nPowerful build\nHeightened senses","weaknesses":"Lack of confidence\nUnrefined power\nOccasional clumsiness","combatStyle":["Strength-based","Instinctive","Power-focused"],"limitations":["Untapped potential","Reluctance to use full strength"],"powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"His greatest limitation is not a lack of power but his uncertainty about using it. Much of his strength remains dormant or restrained.","combatProfile":"Venny''Macon possesses tremendous physical potential but has not fully learned to control or trust it. His werepanther form favors raw strength, durability, and powerful movement rather than refined technique.","weaponDetails":"","transformations":"Sudo Form\nWhite Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses\nEnhanced Speed\nEnhanced Agility","signatureTechniques":"","transformationDetails":"Venny''Macon''s full werebeast form is a magnificent white werepanther with a ghostly white, subtly shimmering coat. He becomes substantially larger and more muscular than a typical panther. His only visible dire wolf trait is a silver patch of fur on his left shoulder. Despite his noble and powerful appearance, his movements can be slightly clumsy and his demeanor remains timid and uncertain."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Claire","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Macon and Venny''Claire are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while his reserved uncertainty contrasts with her playful confidence."}','{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nSturdy muscular build\nNatural linen tunic\nBraided leather waist cord\nLeather sandals\nWhite werepanther form\nSilver left shoulder patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and white werepanther production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e229597e-305b-42fe-b232-1f78f3ac5735/portrait/1790360114514-venny-macon-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish his youthful face, warm brown skin, deep brown eyes, wild 4c hair, sturdy build, linen tunic, braided leather waist cord, and sandals. Werebeast references establish the large ghost-white werepanther design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e229597e-305b-42fe-b232-1f78f3ac5735/reference/1790360121111-venny-macon-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e229597e-305b-42fe-b232-1f78f3ac5735/alternate/1790360126417-venny-macon-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e229597e-305b-42fe-b232-1f78f3ac5735/portrait/1790360114514-venny-macon-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','a13abf6d-6ff2-42f4-a082-2ab7de1c32d4',NULL,'bbe46246-e94b-498d-9ab5-cae88e0804f7','2026-09-25T18:27:18.065698+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('74fd4dac-0364-45fd-9aae-2e363ac3706d','db618e68-0656-4b9b-b308-81e071faf745','Silas','complete','{"age":"","era":"","name":"Silas","race":"Human","alias":"","gender":"Male","titles":"Grand Voodoo Priest","subrace":"","summary":"Silas is the Grand Voodoo Priest of Moonwood Vail and a master of ancestral magic, spiritual crossroads, and curse-weaving. Beneath his witty, carefree persona is a deeply wounded survivor whose family was slaughtered during Captain Blackheart''s pirate raid. He raises and trains his surviving nephew, Sax, while guarding the balance between the physical and spiritual realms. He later becomes a mentor to Kaelen, teaching him spiritual grounding techniques capable of stabilizing Umbral Genesis.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Grand Voodoo Priest","affiliation":"","apparentAge":"40s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""}','{"build":["Tall","Muscular","Broad-shouldered"],"nails":"","eyeHex":["Lilac — #B47AE8"],"height":"6''4\"","makeup":"","weight":"","hairHex":["Black — #111013"],"skinHex":["Deep Ebony — #3A2119"],"eyeColor":["Lilac"],"grooming":"Well-kept beard","skinTone":["Deep ebony"],"wardrobe":"Ritual robes\nLeather wraps\nLayered trousers\nLaced sandals","hairColor":["Black"],"hairStyle":"Long curls with a subtle undercut","accessories":"Bone necklaces\nFeather charms\nBeaded bracelets\nGris-gris charms\nRitual talismans","faceDetails":["Handsome angular face","Thick arched eyebrows","Full beard","Thin connected mustache"],"hairTexture":["4C","Curly"],"colorPalette":"Black — #111013\nDeep Brown — #3A2119\nLilac — #B47AE8\nBone Ivory — #D8C9AA\nDark Purple — #4A284F\nSpirit Green — #72C66A","dominantHand":"","outfitColors":"Black\nDark brown\nDeep purple\nBone ivory","alternateForm":"","clothingStyle":"Ancient spiritual attire combining practical wilderness clothing with ritual adornments. Bones, feathers, animal hides, beads, and intricate lacing visually reflect his connection to ancestral traditions and the spiritual crossroads.","appearanceNotes":"Silas normally presents himself with an easy, goofy smile that reinforces his relaxed and humorous persona. When that mask drops, his expression becomes gloomy and severe, with a blank stare, deep frown, visible rage, and an almost unhinged intensity revealing grief he has never completely healed from.","outfitMaterials":["Animal hide","Leather","Bone","Feathers","Beads","Woven cloth"],"postureMovement":["Relaxed","Confident","Intimidating when serious"],"signatureOutfit":"Layered dark ritual clothing with an open chest, intricate lacing, animal hides, bone adornments, feathers, beads, wraps, and weathered fabric.","distinguishingFeatures":["Voodoo-style tattoos"]}','{"fears":["Losing Sax","Failing his family again","Spiritual imbalance","Shadow Blight corruption"],"goals":["Prepare Sax as a successor","Ground Kaelen''s power","Protect Moonwood Vail","Preserve spiritual equilibrium"],"beliefs":["Ancestor veneration","Harmony with spirits","Balance between realms","Chronoessence connects existence","Spiritual power requires responsibility"],"culture":["Moonwood Vail","Voodoo tradition"],"lineage":"","storyArc":"Silas''s outward humor conceals grief and rage that never fully disappeared after his family''s massacre. His relationship with Sax gives him a reason to remain emotionally connected to the living instead of surrendering himself completely to vengeance. Through mentoring Sax and Kaelen, his role evolves from survivor seeking strength into a guardian responsible for passing that strength forward.","backstory":"Silas eventually married and had a daughter while his brother married and had Sax. At thirty-one, Silas remained home reading while his family went out together. Captain Blackheart''s pirates attacked while searching for a powerful vampire relic and slaughtered Silas''s family. Silas discovered one-year-old Sax alive beneath his mother''s body. Consumed by grief and the need to protect his nephew, Silas devoted himself to Voodoo and eventually rose to become the Grand Voodoo Priest.","childhood":"Silas grew up in the slums of Moonwood Vail with his younger brother and their struggling mother. At thirteen, Silas and his ten-year-old brother vowed to escape poverty and give their mother a better life. Through years of odd jobs and saving, they moved her into a small cottage when Silas was seventeen.","lifestyle":["Spiritual training","Ancestor communion","Ritual practice","Mentoring","Crossroads guardianship"],"storyRole":"Silas serves as a major mentor and spiritual anchor within The Chronicles of Umbra. His mastery of Voodoo allows him to bridge the living world, ancestral realms, and the deeper forces surrounding Chronoessence. His knowledge becomes especially important when he begins teaching Kaelen how to ground the unstable power of Umbral Genesis.","birthplace":"Moonwood Vail","psychology":["Unresolved grief","Suppressed rage","Survivor''s guilt","Protective attachment to Sax","Humor masks emotional pain"],"motivations":["Protect Sax","Honor his family","Maintain spiritual balance","Defend the crossroads","Oppose the Shadow Blight","Avenge his family"],"personality":["Witty","Funny","Carefree","Protective","Strict","Demanding","Resilient","Vengeful"],"voiceSpeech":["Relaxed humor","Playful teasing","Strict teaching voice","Serious when necessary"],"likesDislikes":["Reading","Humor","Spiritual study","Protecting Sax","Pirates"],"majorLifeEvents":"Raised in Moonwood Vail slums\nVowed to escape poverty at thirteen\nMoved his mother from the slums\nMarried and became a father\nCaptain Blackheart''s pirate raid\nFound Sax alive after the massacre\nDevoted himself to Voodoo training\nBecame Grand Voodoo Priest\nBegan training Sax\nBegan mentoring Kaelen"}','{"weapons":"","strengths":"Exceptional spiritual mastery\nAdvanced curse control\nAncestor communication\nCrossroads manipulation\nSpiritual defense\nExperienced mentorship","weaknesses":"Unresolved grief\nSuppressed rage\nProtectiveness toward Sax","combatStyle":["Tactical","Ritual-based","Binding-focused","Curse-based","Spirit-assisted"],"limitations":["Spiritual balance must be maintained"],"powerSource":["Chronoessence","Ancestor spirits","Loa","Spiritual crossroads"],"abilityNotes":"Voodoo in Aethelgard draws upon Chronoessence, ancestral spirits, Loa, nature, and places where the veil between realms is thin. Silas''s mastery makes him capable of maintaining spiritual equilibrium and opposing corruption such as the Shadow Blight. These same principles allow him to teach Kaelen structured spiritual methods for containing and grounding Umbral Genesis.","combatProfile":"Silas approaches conflict through control rather than simple destructive force. He uses spirits, curses, bindings, redirection, and manipulation of spiritual connections to weaken or neutralize opponents. His experience with the crossroads allows him to fight threats that operate across physical and spiritual boundaries.","weaponDetails":"","transformations":"","primaryAbilities":"Ancestor Magic\nSpirit Communion\nCrossroads Magic\nCurse-Weaving\nChronoessence Manipulation","secondaryAbilities":"Spirit Invocation\nSpiritual Binding\nCurse Redirection\nSpiritual Cleansing\nGris-Gris Creation\nRitual Magic\nSpiritual Protection","signatureTechniques":"Ancestor Communion\nCrossroads Invocation\nSpiritual Grounding\nCurse Binding\nCurse Redirection","transformationDetails":""}','{"allies":"Sax\nKaelen","rivals":"","enemies":"Captain Blackheart","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Moonwood Vail","relationshipNotes":"Sax is Silas''s nephew and the only surviving member of his immediate family after Captain Blackheart''s raid. Silas raised, protected, and relentlessly trained him with the possibility that Sax may eventually succeed him as Grand Voodoo Priest. Silas later becomes Kaelen''s mentor, teaching him Voodoo principles to ground and contain Umbral Genesis."}','{"tbdFields":"Age\nWeight\nDominant hand\nBirth date\nParents'' names\nBrother''s name\nWife''s name\nDaughter''s name","canonLocks":"Human\nDeep ebony skin\nLilac eyes\nBlack 4C hair\nSubtle undercut\nFull beard\nThin connected mustache\nThick arched eyebrows\nVoodoo-style tattoos\n6''4\" height\nMuscular build\nBone adornments\nFeather adornments\nAnimal-hide clothing\nHumorous public persona\nGloomy private persona","galleryUrl":"","mediaNotes":"The smiling Silas reference represents the protective persona he commonly presents around Sax. The darker full-body reference represents the grief, fury, and psychological instability beneath that persona.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/74fd4dac-0364-45fd-9aae-2e363ac3706d/portrait/1790360616164-silas-character-portrait.png","visualAssets":"Character Portrait — Done\nAlternate Mood Reference — Done\nSilas and Sax Reference — Done","productionNotes":"Maintain the contrast between Silas''s public persona and his private emotional state. His familiar design should feel warm, charismatic, witty, and slightly mischievous. When the emotional mask drops, preserve the same face and design while replacing the smile with a dark blank stare, severe frown, visible rage, disorientation, and a gloomy aura.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/74fd4dac-0364-45fd-9aae-2e363ac3706d/reference/1790360624556-silas-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/74fd4dac-0364-45fd-9aae-2e363ac3706d/alternate/1790360632228-silas-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/74fd4dac-0364-45fd-9aae-2e363ac3706d/portrait/1790360616164-silas-character-portrait.png',6,1,1,'63782818-208e-4e9b-a57c-9c33daba0589','c68d60d1-883a-4683-8000-a9cd9d0d4d2a',NULL,NULL,'2026-09-25T18:27:14.453024+00:00');
